  'inputs.error': 'खेती की सामग्री अभी लोड नहीं हो सकी — कुछ भी खोया नहीं।',
  'inputs.noCategory': 'प्लेटफ़ॉर्म की सूची में अभी खेती की सामग्री की कोई श्रेणी नहीं है, इसलिए यहाँ दिखाने को कुछ नहीं है।',
  'inputs.empty': '{org} ने अभी कोई खेती की सामग्री सूचीबद्ध नहीं की है।',
  'store2a.browseOff.title': 'ब्राउज़ करना अस्थायी रूप से उपलब्ध नहीं है।',
  'store2a.browseOff.body': 'अभी पूरे प्लेटफ़ॉर्म पर ब्राउज़ करना बंद है। आपके कनेक्शन में कोई खराबी नहीं है — कृपया बाद में लौटें।',
  'store2a.refusal.title': 'यह पृष्ठ क्या नहीं दिखाता या वादा नहीं करता',
  'store2a.refusal.mandi': 'कोई मंडी (APMC) संदर्भ कीमत नहीं दिखाई जाती — उसका कोई लाइसेंसशुदा, स्रोत-सहित आधार नहीं है।',
  'store2a.refusal.tellMeWhen': '“मुझे बताएँ” बटन नहीं है: मेल खाता लॉट आने पर आपको संदेश भेजने वाला कुछ नहीं है।',
  'store2a.refusal.tellMeIfReturns': '“वापस आए तो बताएँ” बटन नहीं है: वह संदेश भेजने वाला कुछ नहीं है।',
  'store2a.refusal.follow': '“फ़ॉलो करें” बटन नहीं है: अगला लॉट आने पर आपको बताने वाला कुछ नहीं है।',
  'store2a.refusal.offline': 'पिछली विज़िट के लॉट ऑफ़लाइन देखने के लिए नहीं रखे जाते, और कार्ट कभी सिंक का इंतज़ार नहीं करता — कार्ट में जोड़ना केवल ऑनलाइन होता है।',
  'store2a.refusal.regionRestricted': 'आपके राज्य के लिए इन परिणामों से चुपचाप कुछ नहीं हटाया जाता — ब्राउज़िंग पर कोई राज्य-प्रतिबंध लागू नहीं होता।',
  'store2a.refusal.multilingual': 'खोज एक साथ कई भाषाओं में नहीं देखती और वर्तनी नहीं सुधारती।',
  'store2a.refusal.voice': 'बोलकर खोजने की सुविधा नहीं है — कृपया शब्द लिखें।',
  'store2a.refusal.closest': 'जब कुछ मेल नहीं खाता, हम यही कहते हैं — कोई “नज़दीकी मिलान” अनुमानित नहीं किया जाता।',
  'store2a.refusal.distance': 'कोई “सबसे नज़दीक पहले”, कोई दूरी, कोई डिलीवरी तारीख और कोई दूरी-आधारित कीमत नहीं दिखाई जाती: कोई स्थान नहीं पूछा जाता।',
  'store2a.refusal.aiGrade': 'कोई मशीनी ग्रेड सुझाव और कोई विश्वास-अंक नहीं दिखाया जाता — केवल वह ग्रेड जिसकी किसी व्यक्ति ने पुष्टि की।',
  'store2a.refusal.priceFee': 'हम यह नहीं कहते कि कीमत में ग्रेडिंग या प्लेटफ़ॉर्म के शुल्क आ जाते हैं: कोई भी शुल्क या कर जोड़ा जाता है और चेकआउट पर दिखाया जाता है।',
  'store2a.refusal.bulk': 'कोई अलग थोक या सत्यापित-खरीदार कीमत नहीं है — सूचीबद्ध कीमत सबके लिए है।',
  'store2a.refusal.dispatchRegrade': 'भेजते समय ग्रेड दोबारा नहीं जाँचा जाता — ऐसा कोई चरण अभी नहीं है।',
  'store2a.refusal.farmer': 'किसान का नाम, फ़ोटो, सदस्य संख्या, ज़मीन और “कब से बेच रहे हैं” की तारीख नहीं दिखाई जाती — विक्रेता संगठन है।',
  'store2a.refusal.badges': 'कोई “KYC सत्यापित”, “केंद्र-ग्रेडेड विक्रेता” या पूरी हुई बिक्री का बैज नहीं दिखाया जाता — संगठन के लिए ऐसा कुछ दर्ज नहीं है।',
  'store2a.refusal.translated': 'समीक्षाएँ उसी भाषा में दिखाई जाती हैं जिसमें लिखी गईं — उनका अनुवाद नहीं होता।',
  'store2a.refusal.fifo': 'बैच नंबर और समाप्ति तिथि नहीं दिखाई जाती, और पुराना स्टॉक पहले भेजने का वादा नहीं किया जाता — अभी किसी ऑर्डर से कोई बैच नहीं जोड़ा जाता।',
  'store2a.refusal.mrp': 'किसी अधिकतम खुदरा मूल्य की सीमा का दावा नहीं किया जाता — इन उत्पादों के लिए कोई MRP दर्ज नहीं है।',
  'store2a.refusal.age': 'इस पृष्ठ पर उम्र की कोई जाँच नहीं होती।',
  'store2a.refusal.labelHelpline': 'यहाँ कोई आपातकालीन फ़ोन लाइन नहीं छापी जाती — उत्पाद के अपने लेबल पर दिए सुरक्षा निर्देश मानें।',
  'store2a.refusal.inputsSwitch': 'खेती की सामग्री की बिक्री हर संगठन के लिए अलग से चालू या बंद नहीं होती — ऐसी कोई सेटिंग नहीं है।',
  'store2a.refusal.flagTenantPlan': 'जब ब्राउज़ करना बंद होता है, तो वह प्लेटफ़ॉर्म पर सबके लिए बंद होता है — किसी एक संगठन या प्लान के लिए नहीं, और इसकी कोई स्टोर सेटिंग नहीं है।',
  'store2a.refusal.oncall': 'लोड न होने वाला पृष्ठ किसी को सूचित नहीं करता; वह आपको फिर से कोशिश करें के साथ दिखाया जाता है।',
  'store2a.refusal.helpline': 'ऑर्डर के लिए कोई फ़ोन लाइन नहीं है — फिर से कोशिश करें, या बाद में इस पृष्ठ पर लौटें।',

