  'store5a.refusal.voice': '"बोलकर लिखें" नहीं है: समीक्षाएँ किसी भी भाषा में टाइप की जाती हैं। कुछ भी रिकॉर्ड या लिप्यंतरित नहीं होता।',
  'store5a.refusal.photos': 'समीक्षा में फ़ोटो नहीं जोड़ी जा सकतीं — अभी फ़ोटो की जाँच की व्यवस्था नहीं है।',
  'store5a.refusal.offline': 'आपके शब्द लिखते-लिखते इस फ़ोन पर रखे जाते हैं — और तभी भेजे जाते हैं जब आप भेजें दबाते हैं: सिग्नल लौटने पर कुछ भी अपने आप नहीं जाता।',
  'store5a.refusal.tonight': 'रेटिंग रात के अपडेट का इंतज़ार नहीं करती — संगठन की रेटिंग कुछ ही मिनटों में अपडेट होती है।',
  'store5a.refusal.maskedName': 'आपकी समीक्षा के साथ कभी कोई नाम, आद्याक्षर या शहर नहीं दिखाया जाता — केवल "सत्यापित खरीदार"।',
  'store5a.refusal.gradingDesk': 'कोई ग्रेडिंग डेस्क या कोल्ड-चेन जाँच विस्तृत रेटिंग नहीं पढ़ती।',
  'store5a.refusal.orgHide': 'संगठन आपकी समीक्षा छिपा, बदल या हटा नहीं सकता — वह जवाब दे सकता है और इसे प्लेटफ़ॉर्म डेस्क के लिए फ़्लैग कर सकता है।',
  'store5a.refusal.flaggedOff': 'यहाँ बदलने को कोई स्टोर सेटिंग नहीं है — समीक्षाएँ बंद हों तो यह पेज बताता है।',
  'store5a.refusal.reconcile': 'समीक्षा करने पर कोई पैसा नहीं चलता — मिलान करने को कुछ नहीं है।',
  'store5a.refusal.oncall': 'असफल होने पर किसी को सूचना नहीं भेजी जाती — यह यहीं बताया जाता है, और आप फिर कोशिश कर सकते हैं।',
  'store5a.refusal.voiceFirst': 'कोई आवाज़-प्रथम मोड नहीं है: इस स्टोर पर कुछ भी सुनता या पढ़कर नहीं सुनाता।',
  'store5a.refusal.speaks': 'बटन छूने पर बोलते नहीं; सीनियर किसान मोड केवल अक्षर और बटन बड़े करता है।',
  'store5a.refusal.helper': 'मोड किसी सहायक द्वारा सेट नहीं किए जाते या आवाज़ से पुष्टि नहीं होते; वे इसी डिवाइस पर चालू किए जाते हैं।',
  'store5a.refusal.everywhere': 'कोई मोड आपके दूसरे फ़ोन या ब्राउज़र पर लागू नहीं होता — हर डिवाइस अपना रखता है।',
  'store5a.refusal.phoneLine': 'यहाँ बराबर के रास्ते के रूप में कोई फ़ोन लाइन या शॉर्ट-कोड मेनू नहीं दिया जाता।',
  'store5a.refusal.sellerPreview': 'इस पेज पर बेचने का कोई पूर्वावलोकन नहीं दिखाया जाता — यह आपके लिए इस स्टोर के दिखने के बारे में है।',
  'store5a.refusal.unaudited': 'अभी दावा नहीं: कि रंग अकेले कभी अर्थ नहीं देता, या स्क्रीन रीडर के लिए पढ़ने का क्रम — इनकी जाँच अभी नहीं हुई है।',
