  'store6b.refusal.voice': 'कोई आवाज़ रिकॉर्ड नहीं होती, और कुछ भी अपने आप नहीं भेजा जाता।',
  'store6b.refusal.conflictCard': 'कोई "फ़ोन वाला रखें" या "हाथ से मिलाएँ" नहीं: ड्राफ़्ट केवल एक फ़ोन पर रहता है, इसलिए कभी दूसरा संस्करण होता ही नहीं।',
  'store6b.refusal.listingDrafts': 'कोई लिस्टिंग ड्राफ़्ट नहीं: इस साइट पर लिस्टिंग नहीं लिखी जातीं।',
  'store6b.refusal.twoPlaces': 'कुछ भी दो जगह नहीं बदला जाता: आपके शब्द केवल इस फ़ोन पर हैं।',
  'store6b.refusal.autoSend': 'सिग्नल लौटने पर कुछ भी अपने आप नहीं भेजा जाता — भेजें आप दबाते हैं।',
  'store6b.refusal.otherDrafts': 'केवल वह संदेश और समीक्षा रखी जाती है जो आप लिख रहे हैं — कभी कार्ट, पता, सेटिंग, ऑफ़र, बोली या साइन-इन फ़ॉर्म नहीं।',
  'store6b.refusal.chainSentences': 'हटाने या इंस्टॉल करने पर सर्वर पर कोई रिकॉर्ड नहीं लिखा जाता, कोई पैसा नहीं चलता, और किसी को सूचना नहीं जाती: ये इस फ़ोन के अपने काम हैं।',
  'store6b.refusal.sizeFigure': 'आमंत्रण कोई डाउनलोड आकार नहीं बताता: कोई मापा नहीं गया।',
  'store6b.refusal.firstVisit': 'आमंत्रण पहली विज़िट पर कभी नहीं दिखाया जाता।',
